head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > focusRemember]<br/>Textarea 컴포넌트에서 포커스를 잃었을 때 이전 커서 위치를 기억할지 설정합니다.",
    "validation" : [
        "IE9 이하 브라우저에서만 동작하며, 그 외 브라우저는 기본적으로 이전 커서 위치를 기억합니다.",
        "미설정 시 이전 커서 위치를 기억하지 않습니다. (기본값 false)",
        "true 설정 시 포커스를 잃었을 때 이전 커서 위치를 기억하고, 다시 포커스를 받으면 해당 위치로 커서를 복원합니다.",
        "false 설정 시 이전 커서 위치를 기억하지 않습니다.",
        "focus() 메소드 호출 시 focusRemember=true 인 경우 저장된 커서 위치로 복원되고, false 인 경우 일반 포커스 동작을 수행합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};


// 현재 커서 위치 (selectionStart, selectionEnd) 를 return textarea 로 출력
scwin.printCaretInfo = function (target, label) {
    let dom = document.querySelector("textarea#" + target.id);
    let msg = label + " -> focusRemember=" + target.options.focusRemember + ", selectionStart=" + dom.selectionStart + ", selectionEnd=" + dom.selectionEnd;
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}


// target1 (focusRemember 미설정 → 기본값 false)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("WebSquare\ntextarea\nfocusRemember test");
};

scwin.btn_focus1_onclick = function (e) {
    target1.focus();
    scwin.printCaretInfo(target1, "[target1] focus() 호출 후");
};

scwin.btn_getCaret1_onclick = function (e) {
    scwin.printCaretInfo(target1, "[target1] 현재 커서 위치");
};


// target2 (focusRemember=true)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("WebSquare\ntextarea\nfocusRemember test");
};

scwin.btn_focus2_onclick = function (e) {
    target2.focus();
    scwin.printCaretInfo(target2, "[target2] focus() 호출 후");
};

scwin.btn_getCaret2_onclick = function (e) {
    scwin.printCaretInfo(target2, "[target2] 현재 커서 위치");
};


// target3 (focusRemember=false)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("WebSquare\ntextarea\nfocusRemember test");
};

scwin.btn_focus3_onclick = function (e) {
    target3.focus();
    scwin.printCaretInfo(target3, "[target3] focus() 호출 후");
};

scwin.btn_getCaret3_onclick = function (e) {
    scwin.printCaretInfo(target3, "[target3] 현재 커서 위치");
};
